func TestEnumAuthStrategySchemaMode(t *testing.T) {
	t.Run("NewFromString_bearer", func(t *testing.T) {
		t.Parallel()
		val, err := NewAuthStrategySchemaModeFromString("bearer")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, AuthStrategySchemaMode("bearer"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_basic", func(t *testing.T) {
		t.Parallel()
		val, err := NewAuthStrategySchemaModeFromString("basic")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, AuthStrategySchemaMode("basic"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_header", func(t *testing.T) {
		t.Parallel()
		val, err := NewAuthStrategySchemaModeFromString("header")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, AuthStrategySchemaMode("header"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewAuthStrategySchemaModeFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewAuthStrategySchemaModeFromString("bearer")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

